<script setup lang="ts">import{ref}from'vue';import{initialAmountState,reduceAmount,amountCents}from'./amount-machine';import{createIndexedDbDatabase}from'../../core/database/indexed-db';const type=ref('支出');const selected=ref('餐饮');const state=ref(initialAmountState());const saved=ref(false);const categories=['餐饮','交通','购物','住房','娱乐','医疗','教育','通讯','旅行','宠物','人情','美容','运动','办公','育儿','汽车','保险','税费','公益','其他'];const save=async()=>{const cents=amountCents(state.value);if(cents<=0)return;const id=crypto.randomUUID(),ledger_id=localStorage.getItem('ledger_id')??'local';const tx={id,ledger_id,amount_cents:cents,occurred_at:new Date().toISOString(),version:1,kind:type.value==='收入'?'income':'expense',category_name:selected.value};const db=await createIndexedDbDatabase();await db.saveWithOutbox(tx,{operation_id:crypto.randomUUID(),ledger_id,entity_type:'transaction',entity_id:id,operation:'upsert',base_version:0,payload:tx});saved.value=true};const press=(k:string)=>{if(k==='完成'){void save();return}state.value=reduceAmount(state.value,k)}</script>
<template><main class="entry-page"><header><button v-for="x in ['支出','收入','转账']" :class="{active:type===x}" @click="type=x">{{x}}</button></header><section class="categories" aria-label="分类"><button v-for="c in categories" :class="{selected:selected===c}" @click="selected=c">{{c}}</button></section><section class="composer"><p v-if="saved" role="status">已保存，待同步</p><div class="amount">¥ {{state.display}}</div><div class="attrs"><button>今天</button><button>现金账户</button><button>成员</button><button>备注</button></div><div class="keypad"><button v-for="k in ['7','8','9','backspace','4','5','6','+','1','2','3','-','.','0','=','完成']" :aria-label="k" @click="press(k)">{{k}}</button></div></section></main></template>
<style scoped>.entry-page{height:100vh;display:grid;grid-template-rows:auto 1fr auto;background:#f7f8f5}.entry-page header{display:flex;gap:8px;padding:12px}.entry-page button{min-height:44px;border:0;border-radius:12px;background:white}.active,.selected{color:#fff!important;background:#718f4b!important}.categories{overflow:auto;display:grid;grid-template-columns:repeat(5,1fr);gap:10px;padding:12px}.composer{background:white;border-radius:24px 24px 0 0;padding:16px}.amount{text-align:right;font-size:36px;font-weight:700}.attrs,.keypad{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px}.keypad button{font-size:20px;background:#eef1ea}</style>
